<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { useSession } from '../stores/session'
import { api, dateText } from '../api'
import { courseContent } from '../courseContent'
import Icon from '../components/Icon.vue'
import DataChart from '../components/DataChart.vue'
import EmptyState from '../components/EmptyState.vue'
const session=useSession(), router=useRouter(), d=ref<any>(null), assignments=ref<any[]>([]), error=ref(false)
const content=computed(()=>courseContent[session.courseId]||courseContent[1])
const today = new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long',timeZone:'Asia/Shanghai'}).format(new Date())
async function load() { error.value=false; try { [d.value,assignments.value]=await Promise.all([api.get(`/courses/${session.courseId}/overview`),api.get(`/courses/${session.courseId}/assignments`)]) } catch { error.value=true } }
onMounted(load)
const stats=computed(()=>!d.value?[]:session.isStudent?[
  {name:'已完成作业',value:d.value.assignment_count-d.value.pending_assignments.length,unit:`/ ${d.value.assignment_count}`,icon:'assignment',color:'blue',note:'按已提交的作业统计'},
  {name:'作业平均分',value:d.value.average_score??'—',unit:'分',icon:'chart',color:'teal',note:'包含建议分与复核分'},
  {name:'待复习错题',value:d.value.mistake_count,unit:'道',icon:'mistakes',color:'orange',note:'把薄弱点变成下一步'},
  {name:'提问消息',value:d.value.question_count,unit:'次',icon:'chat',color:'purple',note:'每次提问都是一次探索'},
]:[
  {name:'课程学生',value:d.value.student_count,unit:'人',icon:'users',color:'blue',note:session.course?.class_name},
  {name:'作业提交',value:d.value.submission_count,unit:'份',icon:'assignment',color:'teal',note:`本次新增 ${d.value.new_count} 份`},
  {name:'待复核批改',value:d.value.pending_review,unit:'份',icon:'review',color:'orange',note:'由教师确认最终评价'},
  {name:'班级平均分',value:d.value.average_score??'—',unit:'分',icon:'chart',color:'purple',note:'按已评分提交统计'},
])
</script>
<template>
  <div class="page-heading"><div><div class="eyebrow">{{ session.isStudent ? 'MY LEARNING SPACE' : 'TEACHING WORKSPACE' }}</div><h1>{{ session.user?.name }}，{{ session.isStudent ? '今天也一起进步' : '让教学更有方向' }} <span class="greeting-dot">✦</span></h1><p>{{ session.isStudent ? '把每一次提问与练习，连接成自己的成长路径。' : '从真实学习记录出发，发现共性问题，给出更及时的反馈。' }}</p></div><span class="date-label"><Icon name="plan" :size="16" />{{ today }}</span></div>
  <div v-if="error" class="panel"><EmptyState title="概览暂时无法加载" description="请确认后端已启动，再点击重试。"><button class="btn btn-primary" @click="load">重新加载</button></EmptyState></div>
  <div v-else-if="!d" class="loading-block"><el-skeleton :rows="12" animated /></div>
  <div v-else data-testid="overview-ready">
    <section class="hero-banner"><div class="hero-copy"><span class="hero-tag"><Icon name="sparkle" :size="14" />{{ session.isStudent ? '你的专属课程助教' : '课程教学，从容掌握' }}</span><h2>{{ session.isStudent ? '不止找到答案，' : '让每一份反馈，' }}<br>{{ session.isStudent ? '更要理解为什么。' : '成为学生的下一步。' }}</h2><p>{{ session.isStudent ? '课程资料为依据，分步提示陪你思考。' : '管理课程依据，复核批改结果，连接教学与学情。' }}</p><button class="btn btn-white" @click="router.push(session.isStudent?'/chat':'/knowledge')">{{ session.isStudent?'向助教提问':'管理课程知识库' }}<Icon name="arrow" :size="17" /></button></div><div class="hero-visual" aria-hidden="true"><span class="orbit orbit-one"></span><span class="orbit orbit-two"></span><div class="floating-pill pill-top"><Icon name="badge" :size="15" />课程依据 · 可追溯</div><div class="visual-paper"><div class="paper-title"><span class="paper-icon"><Icon name="database" :size="22" /></span><div><b>理解，从这里发生</b><small>{{ content.label.toUpperCase() }} · COURSE</small></div></div><div class="paper-code"><span>{{ content.label }}</span> learning<br>practice + reflection<br><em>{{ content.topics }}</em></div><div class="paper-bottom"><span><Icon name="check" :size="13" />连接课程知识</span><i></i><i></i><i></i></div></div><div class="floating-pill pill-bottom"><Icon name="sparkle" :size="15" />每一步，都有回应</div></div></section>
    <section class="stats-grid"><div v-for="card in stats" :key="card.name" class="stat-card"><div class="stat-top"><span>{{ card.name }}</span><span :class="['stat-icon',card.color]"><Icon :name="card.icon" :size="21" /></span></div><div class="stat-value">{{ card.value }}<small>{{ card.unit }}</small></div><div class="stat-note"><span class="mini-dot" :class="card.color"></span>{{ card.note }}</div></div></section>
    <div class="dashboard-grid"><div class="dashboard-main"><section class="panel chart-panel"><div class="section-heading"><div><h3>{{ session.isStudent ? '学习的脚步，看得见' : '作业提交趋势' }}</h3><p class="muted small">最近 7 天 · 按提交记录统计</p></div><span class="subtle-pill">近 7 天<Icon name="down" :size="13" /></span></div><DataChart :data="d.trend" :height="205" /><div class="chart-foot"><span><i></i>作业提交数</span><span><template v-if="d.seed_count">含 {{ d.seed_count }} 条历史演示记录</template><template v-else>根据当前课程真实记录</template></span></div></section>
      <section class="panel"><div class="section-heading"><div><h3>{{ session.isStudent?'继续你的练习':'最近作业提交' }}</h3><p class="muted small">{{ session.isStudent ? '把知识用起来，理解才会更进一步' : '优先关注需要人工复核的反馈' }}</p></div><RouterLink :to="session.isStudent?'/assignments':'/reviews'" class="text-link">查看全部<Icon name="chevron" :size="15" /></RouterLink></div><template v-if="session.isStudent"><div v-for="a in assignments.slice(0,3)" :key="a.id" class="assignment-line"><span class="assignment-icon"><Icon name="code" :size="22" /></span><div class="flex-one"><h4>{{ a.title }}</h4><p class="muted small">{{ a.topic }}<span class="separator">·</span>{{ dateText(a.deadline) }} 截止</p></div><span :class="['tag',a.latest_submission?'green':'orange']">{{ a.latest_submission?'已提交':'待完成' }}</span><button class="icon-btn arrow-circle" aria-label="查看作业" @click="router.push('/assignments?assignment='+a.id)"><Icon name="arrow" :size="17" /></button></div><EmptyState v-if="!assignments.length" title="课程还没有发布作业" /></template><div v-else class="compact-table"><div v-for="s in d.recent_submissions.slice(0,4)" :key="s.id" class="submission-line"><span class="avatar avatar-sm">{{ s.student.slice(0,1) }}</span><div class="flex-one"><h4>{{ s.student }}<span v-if="s.is_seed" class="seed-inline">样例</span></h4><p class="muted small">{{ s.title }}</p></div><strong>{{ s.score??'待评' }}<small v-if="s.score!==null"> 分</small></strong><span :class="['tag',s.reviewed?'green':'orange']">{{ s.reviewed?'已复核':'待复核' }}</span></div><EmptyState v-if="!d.recent_submissions.length" title="暂时没有提交记录" /></div></section>
    </div><div class="dashboard-side"><section v-if="session.isStudent" class="panel checklist-panel"><div class="section-heading"><h3>接下来，做一点小事</h3><Icon name="target" :size="20" class="text-blue" /></div><p class="muted small">循序渐进，比一口气学完更重要</p><div class="next-step" v-for="(a,i) in d.pending_assignments.slice(0,2)" :key="a.id"><span class="step-check">{{ Number(i)+1 }}</span><div><b>{{ a.topic }}专项练习</b><small>{{ dateText(a.deadline) }} 前完成</small></div><RouterLink :to="'/assignments?assignment='+a.id"><Icon name="chevron" :size="17" /></RouterLink></div><div class="next-step"><span class="step-check pale-purple"><Icon name="mistakes" :size="15" /></span><div><b>回顾我的错题</b><small>{{ d.mistake_count }} 道错题等待重新理解</small></div><RouterLink to="/mistakes"><Icon name="chevron" :size="17" /></RouterLink></div><RouterLink to="/plans" class="full-soft-link">制定我的学习计划<Icon name="arrow" :size="15" /></RouterLink></section>
      <section v-else class="panel"><div class="section-heading"><h3>高频错误分布</h3><span class="subtle-pill">全部提交</span></div><DataChart v-if="d.error_distribution.length" :data="d.error_distribution" type="pie" :height="220" /><EmptyState v-else title="暂无错误记录" description="有批改记录后显示分布。" /><p class="muted small">源于当前课程错题记录，历史样例保留标记。</p></section>
      <section class="panel"><div class="section-heading"><h3>{{ session.isStudent?'错题复习进度':'需要关注的学生' }}</h3><Icon :name="session.isStudent?'layers':'users'" :size="19" class="muted" /></div><template v-if="session.isStudent"><div v-for="topic in d.topics.filter((t:any)=>t.total).slice(0,3)" :key="topic.name" class="topic-progress"><div><span>{{ topic.name }}</span><small>{{ topic.mastered }} / {{ topic.total }}</small></div><div class="progress-track"><i :style="{width: topic.rate+'%'}"></i></div></div><p class="muted small mt16">根据手动复习标记统计，不代表实测掌握度。</p></template><template v-else><div v-for="(s,i) in d.attention.slice(0,3)" :key="i" class="attention-line"><span class="avatar avatar-sm">{{ s.name.slice(0,1) }}</span><span>{{ s.name }}</span><span class="muted small">{{ s.pending }} 个待复习点</span></div><EmptyState v-if="!d.attention.length" title="暂无待关注记录" /></template></section>
      <section class="panel activity-panel"><div class="section-heading"><h3>最近动态</h3><Icon name="clock" :size="18" class="muted" /></div><div v-for="e in d.events.slice(0,3)" :key="e.id" class="activity-item"><span class="activity-dot"></span><div><p>{{ e.text }}</p><small>{{ dateText(e.created_at,true) }}{{ e.is_seed?' · 样例':'' }}</small></div></div><p v-if="!d.events.length" class="muted small">从一次提问开始，留下你的学习足迹。</p></section>
    </div></div>
  </div>
</template>
